// Component (Category B) — an ordered list whose items are joined by a rail between their marks.
//
// No headless primitive: React Aria has no timeline, and the behaviour is none (a list is read,
// not operated), so it is semantic HTML: an `<ol>` of `<li>`s. What it OWNS is the look a Block
// cannot draw, the rail, which is why ActivityFeed asked for it (block-contract.md §5: a Block
// owns no look). Peer systems ship the same shape (Mantine, Ant Design and Chakra each have a
// Timeline whose item carries a mark and a tail line).
//
// The mark is a slot, not a variant: an Avatar for who did something, an icon or a status dot for
// what happened. It leads a line of text, so where it starts on the page is the composing Block's
// call (component-contract.md §6 rule 8), and the item takes the Block's `className` for that.
import type { HTMLAttributes, LiHTMLAttributes, ReactNode, Ref } from "react";
import "./Timeline.css";

export interface TimelineProps extends Omit<HTMLAttributes<HTMLOListElement>, "className"> {
  /** `TimelineItem`s, in order. */
  children: ReactNode;
  /** Additional class. sd-timeline is always preserved. */
  className?: string;
  /** Forwarded to the `<ol>`. */
  ref?: Ref<HTMLOListElement>;
}

export function Timeline({ children, className, ref, ...props }: TimelineProps) {
  return (
    <ol {...props} ref={ref} className={className ? `sd-timeline ${className}` : "sd-timeline"}>
      {children}
    </ol>
  );
}

export interface TimelineItemProps extends Omit<LiHTMLAttributes<HTMLLIElement>, "className"> {
  /** The mark the rail joins: an Avatar, an icon, a status dot. */
  indicator: ReactNode;
  /** What happened. */
  children: ReactNode;
  /** Additional class. sd-timeline__item is always preserved. */
  className?: string;
  /** Forwarded to the `<li>`. */
  ref?: Ref<HTMLLIElement>;
}

export function TimelineItem({ indicator, children, className, ref, ...props }: TimelineItemProps) {
  return (
    <li
      {...props}
      ref={ref}
      className={className ? `sd-timeline__item ${className}` : "sd-timeline__item"}
    >
      <span className="sd-timeline__track">
        <span className="sd-timeline__indicator">{indicator}</span>
        {/* Drawn, not read: the order is the list's, and a line has nothing to announce. */}
        <span className="sd-timeline__rail" aria-hidden="true" />
      </span>
      <div className="sd-timeline__content">{children}</div>
    </li>
  );
}

/* Timeline.css — .sd-timeline (+ BEM sub-parts)
   sd- prefix / single flat class / no descendant combinators / Cmp tokens only.
   Each item is [track | content]; the track holds the mark and, under it, the rail that runs the
   item's full height to the next mark. The last item has no rail and no trailing gap, carried by
   two `-current` relays the item sets for its own descendants, because a descendant combinator
   (`:last-child .rail`) is not allowed here. */
.sd-timeline {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sd-timeline__item {
  --sd-timeline-rail-display-current: block;
  --sd-timeline-content-padding-block-end-current: var(--sd-timeline-gap);
  display: flex;
  gap: var(--sd-timeline-item-gap);
}
.sd-timeline__item:last-child {
  --sd-timeline-rail-display-current: none;
  --sd-timeline-content-padding-block-end-current: 0px;
}

.sd-timeline__track {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: center;
}

.sd-timeline__indicator {
  display: flex;
}

/* The rail grows to fill whatever height the item has left under the mark, so a long entry and a
   short one are joined the same way. A border rather than a background, so the dashed style is the
   token's to choose. */
.sd-timeline__rail {
  display: var(--sd-timeline-rail-display-current);
  flex: 1;
  margin-block: var(--sd-timeline-rail-gap);
  border-inline-start: var(--sd-timeline-rail-width) var(--sd-timeline-rail-style) var(--sd-timeline-rail-color);
}

/* The gap to the next item is spent HERE, inside the item, so the rail above reaches across it. */
.sd-timeline__content {
  flex: 1;
  min-width: 0;
  padding-block-end: var(--sd-timeline-content-padding-block-end-current);
}
